INSERT INTO gm.exercise_revision (exercise_id,revision,type,payload,rubric,normalization_version,provenance,review_status) VALUES ('81000000-0000-4000-8000-000001160080','1','gap_choice','{"type":"gap_choice","schemaVersion":1,"id":"81000000-0000-4000-8000-000001160080","revision":1,"targetId":"80000000-0000-4000-8000-000000011608","prompt":"In Köln ziehen im Februar oft bunte Wagen durch die Straßen; die Menschen feiern ___.","instruction":{"en":"Choose the noun or noun form that best completes the German sentence.","de":"Wähle das Nomen oder die Nomenform, die den deutschen Satz sinnvoll ergänzt."},"hint":{"en":"The festival includes colourful parades.","de":"Das Fest umfasst bunte Umzüge."},"slots":[{"id":"noun","label":"Nomen oder Form","options":[{"id":"0","text":"Weihnachten"},{"id":"1","text":"Karneval"},{"id":"2","text":"Ostern"},{"id":"3","text":"Silvester"}]}]}','{"normalizationVersion":"de-nfc-trim-v1","acceptedAnswers":[{"type":"gap_choice","selections":[{"slotId":"noun","optionId":"1"}]}],"explanation":{"en":"Karneval means carnival festival here; \"Karneval\" fits the intended context.","de":"Karneval bedeutet hier Karneval als Kostümfest; die Form „Karneval“ passt zum Kontext."},"completedAnswer":{"schemaVersion":1,"parts":[{"text":"In Köln ziehen im Februar oft bunte Wagen durch die Straßen; die Menschen feiern Karneval.","emphasis":false}]}}','de-nfc-trim-v1','Original GPT-6 exercises from pinned lexical and grammar facts apps/web/data/pos/nouns.jsonl:L1226 (4cb813a9f6e146fa6954b8fd02b4ed4473f839cf1990daf0e6447c0ef8b1143d), 2026-10-29. Inherited examples not copied. Owner-authorized basic release by Owner direction 2026-11-04 at 2026-11-04T22:00:00Z; GPT-6 AI editorial/rubric checks; independent human review not required by owner. Authorization: Reviewed = editorially approved; only exact semantically rechecked corrections or nonblocking originals may be included.','approved');
